using NUnit.Framework;using LighFight.Core;
public sealed class CloseCombatV2Tests {
 [Test]public void PhysicalApproachContactIsNotDiscardedBeforeNominalActiveFrame(){var m=new Match(true);m.RequirePhysicalContact=true;m.ContactValidator=(attacker,target)=>attacker.Frame==2;m.A.Start(0);for(int i=0;i<5;i++)m.Step();Assert.AreEqual(144,m.B.Health,"Actual approach contact cannot be discarded while the animation continues through the body");Assert.AreEqual(1,m.B.HitSerial);}
 [TestCase(1)][TestCase(-1)]public void ExistingRootOverlapIsRepairedWithoutCrossing(int direction){var m=new Match(true);m.A.X=direction*-.05f;m.B.X=direction*.05f;m.A.FacingX=direction;m.B.FacingX=-direction;m.Step();Assert.GreaterOrEqual(Match.Distance(m.A,m.B),Match.MinimumSeparation-.00001f);Assert.Greater((m.B.X-m.A.X)*direction,0);for(int tick=0;tick<120;tick++){m.Walk(m.A,direction);m.Walk(m.B,-direction);m.Step();Assert.GreaterOrEqual((m.B.X-m.A.X)*direction,Match.MinimumSeparation-.00001f);}}
 [Test]public void PhysicalMissCannotDamageByProximity(){var m=new Match(true);m.A.X=-.3f;m.B.X=.3f;m.RequirePhysicalContact=true;m.ContactValidator=(a,b)=>false;m.A.Start(0);for(int i=0;i<50;i++)m.Step();Assert.AreEqual(150,m.B.Health);}

 [TestCase(1)][TestCase(-1)]public void FastPunchAndKickCannotTunnelThroughMovingBody(int side){foreach(float height in new[]{.5f,1.4f}){var from=new ContactVector(-side, height,0);var to=new ContactVector(side,height,0);var c=new ContactVector(0,.2f,0);var d=new ContactVector(0,1.6f,0);var hit=SweptContact.Cast(from,from,to,to,c,d,c,d,.2f);Assert.True(hit.Hit);Assert.False(hit.Indeterminate);Assert.That(hit.Time,Is.InRange(.35f,.45f));var miss=SweptContact.Cast(from+new ContactVector(0,0,1),from+new ContactVector(0,0,1),to+new ContactVector(0,0,1),to+new ContactVector(0,0,1),c,d,c,d,.2f);Assert.False(miss.Hit);Assert.False(miss.Indeterminate);}}
 [Test]public void DefenderCrossingStationaryStrikeIsSweptToo(){var p=new ContactVector(0,1,0);var c0=new ContactVector(-1,.5f,0);var d0=new ContactVector(-1,1.5f,0);var c1=new ContactVector(1,.5f,0);var d1=new ContactVector(1,1.5f,0);Assert.True(SweptContact.Cast(p,p,p,p,c0,d0,c1,d1,.2f).Hit);Assert.True(SweptContact.Cast(p,p,p,p,c0,d0,c1,d1,.2f,0).Indeterminate);}

 [Test]public void SourceStrikeReturnIsBoundedAndCompletesWithoutFreezing(){float previous=10;for(int frame=11;frame<30;frame++){float current=MotionTiming.StoppedFrame(10,10,frame,28);Assert.LessOrEqual(current,previous);Assert.GreaterOrEqual(current,0);previous=current;}Assert.AreEqual(0,previous);Assert.AreEqual(10,MotionTiming.StoppedFrame(10,10,11,28));}
 [TestCase(true)][TestCase(false)]public void CrouchedAndGuardedPhysicalContactsRemainGeometric(bool crouch){var m=new Match(true);m.RequirePhysicalContact=true;m.B.Guard=true;m.B.Crouch=crouch;m.ContactValidator=(a,b)=>a.Frame==2;m.A.Start(crouch?5:0);for(int i=0;i<10;i++)m.Step();Assert.AreEqual(150,m.B.Health);Assert.AreEqual(1,m.B.HitSerial);Assert.True(m.B.LastBlocked);}
}
